describe("lastLoginMethod beforeStoreCookie", async () => {
	const run = async (beforeStoreCookie: () => unknown, cookieName?: string) => {
		const { client, testUser } = await getTestInstance({
			plugins: [
				lastLoginMethod({
					beforeStoreCookie: beforeStoreCookie as never,
					cookieName,
				}),
			],
		});
		let setCookie = "";
		const res = await client.signIn.email(
			{ email: testUser.email, password: testUser.password },
			{
				onSuccess(context) {
					setCookie = context.response.headers.get("set-cookie") || "";
				},
			},
		);
		return { res, setCookie, name: cookieName ?? "better-auth.last_used_login_method" };
	};

	it("sets the cookie when the hook resolves truthy", async () => {
		const hook = vi.fn(async () => true);
		const { setCookie, name } = await run(hook);
		expect(setCookie).toContain(`${name}=email`);
		expect(hook).toHaveBeenCalledWith(
			expect.objectContaining({ path: "/sign-in/email" }),
			"email",
		);
	});

	it.each([false, 0])("skips the cookie when the hook returns %s", async (v) => {
		const { res, setCookie, name } = await run(() => v);
		expect(res.data?.token).toBeTruthy();
		expect(setCookie).not.toContain(name);
	});

	it("skips the cookie when the hook throws or rejects", async () => {
		for (const hook of [
			() => {
				throw new Error("boom");
			},
			async () => {
				throw new Error("boom");
